import {drawCore} from './core-art.mjs?v=4.9c';
import {drawAdventure} from './printer-adventure-art.mjs?v=4.9c';
import {drawDragon,dragonPose,dragonCore} from './dragon.mjs?v=4.9c';
const line=(c,x,y,xx,yy,color,w=3)=>{c.strokeStyle=color;c.lineWidth=w;c.beginPath();c.moveTo(x,y);c.lineTo(xx,yy);c.stroke();};
function screen(c,x,y,text,small=''){c.fillStyle='#102033';c.fillRect(x,y,240,75);c.strokeStyle='#77a4b2';c.lineWidth=3;c.strokeRect(x,y,240,75);c.fillStyle='#b7e9dc';c.font='bold 15px monospace';c.textAlign='left';c.fillText(text,x+12,y+26);c.fillStyle='#edbd90';c.font='12px sans-serif';c.fillText(small,x+12,y+53);}
function nozzle(c,x,y){c.fillStyle='#adcccb';c.fillRect(x-28,y-30,56,25);c.fillStyle='#18384b';c.fillRect(x-18,y-24,36,9);c.fillStyle='#ecc291';c.beginPath();c.moveTo(x-12,y-5);c.lineTo(x+12,y-5);c.lineTo(x,y+12);c.fill();}
export function drawJourney(c,g){const s=g.printer;if(!s)return;const j=s.journey,t=g.time,r=g.rooms.active,b=s.boss;c.save();
 for(const a of g.level.platforms.filter(a=>a.y===680)){c.fillStyle='#88cfbc';c.fillRect(a.x,a.y,a.w,5);for(let x=a.x+25;x<a.x+a.w;x+=50){c.fillRect(x,a.y+9,20,3);}}
 for(const z of g.level.fallZones.filter(z=>z.room===r)){c.strokeStyle='#d1a17d';c.lineWidth=3;c.setLineDash([12,12]);c.beginPath();c.moveTo(z.x,z.y-6);c.lineTo(z.x+z.w,z.y-6);c.stroke();c.setLineDash([]);}

 if(r==='A'){screen(c,40,115,'DRAGON-01  '+j.progress+'%','DRAGON用 シルクPLA 3kg');line(c,955,450,1030,340,'#537689',12);line(c,955,450,1030,340,j.holder?'#f4c598':'#4f6478',3);c.strokeStyle=j.holder?'#b5ffde':'#e6ba94';c.lineWidth=8;c.beginPath();c.arc(950,455,36,0,7);c.stroke();if(j.holder){c.save();c.translate(950,455);c.rotate(t*4*j.capture);c.fillStyle='#e5b58c';for(let i=0;i<8;i++){c.rotate(Math.PI/4);c.fillRect(7,-3,24,6);}c.restore();line(c,980,450,1040,340,'#ffe4b6',2);}}
 if(r==='B2'){c.strokeStyle=j.bonusHolder?'#baffd9':'#d6b68e';c.lineWidth=7;c.beginPath();c.arc(11880,455,36,0,7);c.stroke();line(c,11880,425,11920,200,'#c3e6df',3);}
 if(r==='B'||r==='B2'){const x=r==='B'?1490:10300;screen(c,x,55,'DRAGON / JOINT '+j.progress+'%','JOB 2/2');c.globalAlpha=.45;c.fillStyle='#7a9aa9';for(let i=0;i<4;i++){c.fillRect(x+i*45,145,30,18);c.fillRect(x+8+i*45,135,15,42);}c.globalAlpha=1;}
 if(r==='C'||r==='C2'){const x=r==='C'?2730:14850;screen(c,x,55,'JOB 2/2  '+j.progress+'%',s.incident&&!j.runawaySolved?'FEED OVERRUN':'DRAGON-01');if(s.incident&&!j.runawaySolved){c.strokeStyle='#e4a589';c.lineWidth=22;c.beginPath();for(let i=0;i<9;i++){const xx=x-80+i*35,yy=475-i*8;c.lineTo(xx,yy);}c.stroke();for(let i=0;i<9;i++){c.fillStyle='#d3a3b8';c.fillRect(x-90+i*35,440-i*8,22,30);}c.fillStyle=Math.sin(t*5)>0?'#e8ac89':'#6d4557';c.fillRect(x+35,145,30,8);}}
 if(r==='D'||r==='D2'){screen(c,r==='D'?4930:17820,100,'DRAGON '+j.progress+'%','DESIGN / ARTICULATED');if(r==='D'){c.save();c.globalAlpha=.22;c.translate(5220,350);c.scale(.32,.32);drawDragon(c,{...b,x:0,y:0,age:10,clock:0,phase:1,done:true,stoppedAge:3},t);c.restore();}}
 for(const site of g.level.printSites){if(site.room!==r)continue;const state=j.sites[site.id];c.strokeStyle='#dbba95';c.lineWidth=2;c.beginPath();c.moveTo(site.x,site.y-20);c.lineTo(site.blocks[0][0],site.blocks[0][1]-20);c.stroke();
 for(const [x,y,w,h=18] of site.blocks){if(state.progress>=1)continue;c.strokeStyle='#d6c0a4';c.setLineDash([5,6]);c.strokeRect(x,y,w,h);c.setLineDash([]);c.fillStyle='#dbbc92';for(let k=0;k<Math.floor(state.progress*Math.max(8,h/3));k++)c.fillRect(x,y+h-k*3,w,2);if(state.active)nozzle(c,x+(Math.sin(t*5)*.5+.5)*w,y+h-state.progress*h-25);}}
 for(const a of g.level.cargoObstacles){c.fillStyle='#162c3e';c.fillRect(a.x,a.y,a.w,a.h);c.fillStyle='#f4c18c';for(let k=0;k<5;k++)c.fillRect(a.x+k*10,a.y,5,a.h);line(c,a.x+a.w/2,100,a.x+a.w/2,a.y,'#688798',5);}
 for(const a of g.level.platforms.filter(a=>a.coreStair)){if(b.frame<=0||b.cooled)continue;c.fillStyle='#e7bb91';for(let k=0;k<Math.floor(b.frame*6);k++)c.fillRect(a.x,a.y+18-k*3,a.w,2);}
 // Consistent, bright landing marks on the safe body/stairs and a visible final core.
 if(b.cooled){const core=dragonCore(b),n={x:core.x+core.w/2,y:core.y+core.h/2};line(c,n.x,n.y+30,n.x,n.y+105,'#829fa9',10);c.fillStyle='#16354b';c.fillRect(n.x-26,n.y-27,52,54);drawCore(c,n.x,n.y,t,!!b.finalHit);if(b.finalHit){line(c,n.x-18,n.y-20,n.x+4,n.y+2,'#fcfff4',5);line(c,n.x+4,n.y+2,n.x-10,n.y+22,'#fcfff4',5);}if(b.beacon>0)line(c,6450,260,n.x,n.y,'#c6ffdd',2);c.strokeStyle='#fff0b6';c.lineWidth=4;c.beginPath();c.arc(n.x,n.y,43+Math.sin(t*5)*3,0,7);c.stroke();line(c,n.x-11,n.y-13,n.x+2,n.y,'#fcf5d3');line(c,n.x+2,n.y,n.x-5,n.y+16,'#fcf5d3');}
 for(const e of s.foes){const age=t-(e.deathTime??-100);if(e.alive||age>.55)continue;c.fillStyle='#e9b7bd';for(let k=0;k<6;k++){const a=k*Math.PI/3;c.fillRect(e.x+20+Math.cos(a)*age*95,e.y+20+Math.sin(a)*age*80+age*age*100,7-age*9,7-age*9);}}
 drawAdventure(c,g);c.restore();}
export function drawDawn(c,g,w,h){const end=g.printer?.ending;if(!end?.active)return;const age=end.age;c.save();const sky=c.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#9ca3ba');sky.addColorStop(1,'#edc59e');c.fillStyle=sky;c.fillRect(0,0,w,h);const cx=w/2;c.fillStyle='#e7d6ad';c.fillRect(cx-180,65,360,240);c.fillStyle='#7892a4';for(let i=0;i<3;i++)c.fillRect(cx-170+i*120,75,105,210);c.fillStyle='#47596c';c.fillRect(cx-270,410,540,18);c.fillRect(cx-240,428,15,172);c.fillRect(cx+220,428,15,172);
 c.save();c.translate(cx+100,402);c.scale(.19,.19);drawDragon(c,{...g.printer.boss,x:0,y:0,age:10,phase:1,done:true,stoppedAge:3,clock:0},0);c.restore();
 const wake=Math.min(1,Math.max(0,(age-1.2)*1.3));c.fillStyle='#b4a3dd';c.fillRect(cx-190,380-wake*45,47,65);c.fillStyle='#e4b69b';c.fillRect(cx-183,350-wake*45,32,32);c.fillStyle='#273649';c.fillRect(cx-185,345-wake*45,37,12);c.fillStyle='#203547';c.fillRect(cx-178,365-wake*45,10,wake>0?4:1);c.fillRect(cx-164,365-wake*45,10,wake>0?4:1);
 line(c,cx-177,385-wake*35,cx-200,408,'#e4b69b',8);c.fillStyle='#263949';c.fillRect(cx-180,361-wake*45,12,8);c.fillRect(cx-165,361-wake*45,12,8);line(c,cx-168,364-wake*45,cx-165,364-wake*45,'#263949',2);c.fillStyle='#b7d9d1';c.fillRect(cx-178,363-wake*45,7,2);c.fillRect(cx-163,363-wake*45,7,2);c.fillStyle='#c8b98e';c.fillRect(cx-50,392,15,18);
 c.textAlign='center';c.fillStyle='#172c40';c.font='bold 22px sans-serif';c.fillText('翌朝 / 試作品の設計者',cx,52);if(age>2){c.fillStyle='#163047';c.fillRect(cx-190,170,380,65);c.fillStyle='#f6edcf';c.font='bold 26px sans-serif';c.fillText('……できてる',cx,212);}c.restore();}
